css:
/* Header: navy bar, logo left, nav + quote button right. */
[data-bz-node="header"] { background: var(--accent); color: var(--hcm-nav-link); padding-block: 16px; }
[data-bz-node="header-row"] { align-items: center; }
[data-bz-node="logo"] .bz-logo__img { height: clamp(36px, 5vw, 54px); }
[data-bz-node="header-nav"], [data-bz-node="header-cta"] { display: flex; justify-content: flex-end; }
[data-bz-node="main-nav"] .bz-menu-wrap { justify-content: flex-end; }
[data-bz-node="main-nav"] .bz-nav { gap: clamp(12px, 2vw, 30px); }
[data-bz-node="main-nav"] .bz-navitem > a { font: 600 clamp(14px, 1.6vw, 17px)/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; color: var(--hcm-nav-link); }
[data-bz-node="main-nav"] .bz-navitem > a:hover, [data-bz-node="main-nav"] .bz-navitem > a[aria-current="page"] { color: #fff; }
[data-bz-node="main-nav"] .bz-menu-toggle { width: 44px; height: 44px; align-items: center; justify-content: center; color: #fff; border: 1.5px solid rgb(255 255 255 / 50%); }
[data-bz-node="main-nav"] .bz-menu-toggle span { width: 20px; }
[data-bz-node="header-button"] .bz-btns { margin: 0; flex-wrap: nowrap; }
[data-bz-node="header-button"] .bz-btn { background: #fff; border-color: #fff; color: var(--accent); font-size: clamp(14px, 1.6vw, 17px); font-weight: 600; padding: 11px 26px; white-space: nowrap; }
[data-bz-node="header-button"] .bz-btn:hover { background: var(--hcm-nav-link); border-color: var(--hcm-nav-link); color: var(--accent); }
/* The design collapses the nav at 860px rather than the platform's 1100px. */
@media (min-width: 861px) and (max-width: 1100px) {
  [data-bz-node="main-nav"] .bz-menu-toggle { display: none; }
  [data-bz-node="main-nav"] .bz-menu-wrap > .bz-menu { display: flex; }
  [data-bz-node="header-row"] { display: flex; gap: 16px; }
  [data-bz-node="header-brand"], [data-bz-node="header-cta"] { flex: none; }
  [data-bz-node="header-nav"] { flex: 1 1 auto; }
  [data-bz-node="header-button"] .bz-btn { padding: 11px 18px; }
}
@media (max-width: 860px) {
  [data-bz-node="header"] > .bz-container { position: relative; }
  [data-bz-node="header-row"] { display: flex; flex-wrap: nowrap; justify-content: space-between; gap: 12px; }
  [data-bz-node="header-brand"] { flex: 1 1 auto; }
  [data-bz-node="header-nav"], [data-bz-node="header-cta"] { flex: none; position: static; }
  [data-bz-node="header-nav"] { order: 3; }
  [data-bz-node="main-nav"], [data-bz-node="main-nav"] .bz-menu-wrap { position: static; }
  [data-bz-node="header-button"] .bz-btn { padding: 10px 16px; font-size: 14px; }
  [data-bz-node="main-nav"] .bz-menu-wrap[data-open] > .bz-menu { z-index: 20; background: var(--accent); border-top: 1px solid rgb(255 255 255 / 12%); border-bottom: 0; padding: 8px var(--container-pad-tablet) 20px; }
  [data-bz-node="main-nav"] .bz-menu-wrap[data-open] .bz-nav { align-items: stretch; gap: 0; }
  [data-bz-node="main-nav"] .bz-menu-wrap[data-open] .bz-navitem > a { display: block; font-size: 18px; padding: 14px 0; border-bottom: 1px solid rgb(255 255 255 / 8%); }
}
@media (max-width: 640px) {
  [data-bz-node="main-nav"] .bz-menu-wrap[data-open] > .bz-menu { padding-inline: var(--container-pad-mobile); }
}

/* Footer bottom bar */
[data-bz-node="footer-bar"] { background: var(--ink-dark); color: var(--hcm-on-navy-3); font-size: 12px; padding-block: 16px; }
[data-bz-node="footer-bar-row"] { align-items: center; row-gap: 8px; }
[data-bz-node="footer-bar"] .bz-block p { margin: 0; font-size: 12px; line-height: 1.5; }
[data-bz-node="footer-copy"] { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 0; }
[data-bz-node="footer-copy"] > .bz-block { margin: 0; }
[data-bz-node="legal-nav"] .bz-nav { gap: 0; }
[data-bz-node="legal-nav"] .bz-navitem::before { content: "·"; padding-inline: 6px; }
[data-bz-node="legal-nav"] .bz-navitem > a { font: 400 12px/1.5 var(--font-body); padding: 0; color: var(--hcm-on-navy-3); }
[data-bz-node="legal-nav"] .bz-navitem > a:hover { color: #fff; }
[data-bz-node="footer-powered"] p { text-align: right; }
@media (max-width: 640px) { [data-bz-node="footer-powered"] p { text-align: left; } }
